class DEVFileWriterCSV
{
    TextStreamIo    ioData;
    str             fieldDelimiter;

}

Method.Source:
public void init(str _inFieldDelimiter = ',')
{
    #File

    fieldDelimiter = _inFieldDelimiter;

    ioData = TextStreamIo::constructForWrite(0);
    ioData.inFieldDelimiter(fieldDelimiter);
    ioData.outFieldDelimiter(fieldDelimiter);
    ioData.inRecordDelimiter(#delimiterCRLF);
}
